mapper.select:
		select 
		  sch_id as schId, /* 方案代码 */
		  sch_name as schName, /* 方案名 */
          IS_DEFAULT as isDefault
        from BOK_SCHEME_INFO
        where scheme_type = '02'

                AND (SCH_ID like '%' || #{searchKey} || '%' 
                    OR SCH_NAME like '%' || #{searchKey} || '%')




                AND (SCH_ID like '%' || #{search} || '%' 
                    OR SCH_NAME like '%' || #{search} || '%')




                AND (SCH_ID = #{schId}
                 OR   SCH_NAME = #{schName}
                )


                AND SCH_NAME = #{schName}




                AND SCH_ID != #{owner}

select t.seq_no as seqNo, /* 流水号 */ t.sch_id as schId, /* 方案代码 */ b.IS_DEFAULT as isDefault ,/**是否默认**/ t.asset_classify as assetClassify, /* 资产分类 */ t.asset_classify as assetClassifyCode, t.capi_income_feature as capiIncomeFeature, /* 本金收益特征 */ t.capi_income_feature as capiIncomeFeatureCode, t.income_type as incomeType, /* 收入类型 */ t.income_type as incomeTypeCode, t.taxable_sign as taxableSign, /* 应税标志 - 计税方式 */ t.taxable_sign as taxableSignCode, t.fee_type as feeType, /* 免税收入类型 */ t.fee_type as feeTypeCode, t.tax_rate*100 as taxRate, /* 应税税率(%) */ TO_CHAR(t.eff_date, 'yyyy-MM-dd') as effDate/* 生效日 */ from TAX_VAT_SCHEDULE t left join BOK_SCHEME_INFO b on t.SCH_ID=b.SCH_ID and b.SCHEME_TYPE='02'
AND t.seq_no in
#{item}
AND t.SCH_ID = #{schId}
AND t.asset_classify in
#{item}
AND t.capi_income_feature in
#{item}
AND t.income_type in
#{item}
AND t.fee_type in
#{item}
and t.eff_date >= to_date(#{effDateBegin},'yyyy-mm-dd')
and t.eff_date <= to_date(#{effDateEnd},'yyyy-mm-dd')
and t.eff_date = to_date(#{effDate},'yyyy-mm-dd')
AND t.seq_no != #{owner}

select t.tax_id as taxId, /*税则代码 */ t.sch_id as schId, /* 方案代码 */ b.IS_DEFAULT as isDefault ,/**是否默认**/ t.add_tax_type as addTaxType, /* 附加税类型 */ t.add_tax_type as addTaxTypeCode, t.tax_rate*100 as taxRate, /* 应税税率(%) */ TO_CHAR(t.eff_date, 'yyyy-MM-dd') as effDate/* 生效日 */ from TAX_ADT_SCHEDULE t left join BOK_SCHEME_INFO b on t.SCH_ID=b.SCH_ID
AND t.tax_id in
#{item}
AND t.SCH_ID = #{schId}
AND t.add_tax_type in
#{item}
and t.eff_date >= to_date(#{effDateBegin},'yyyy-mm-dd')
and t.eff_date <= to_date(#{effDateEnd},'yyyy-mm-dd')
and t.eff_date = to_date(#{effDate},'yyyy-mm-dd')
AND t.tax_id != #{owner}

select t.tax_id as taxId, /*税则代码 */ t.sch_id as schId, /* 方案代码 */ b.IS_DEFAULT as isDefault ,/**是否默认**/ t.add_tax_type as addTaxType, /* 附加税类型 */ t.add_tax_type as addTaxTypeCode, t.tax_rate*100 as taxRate, /* 应税税率(%) */ TO_CHAR(t.eff_date, 'yyyy-MM-dd') as effDate/* 生效日 */ ,dani.INSTITUTION_CODE belongInstitutionCode ,'01' updateFlg from TAX_ADT_SCHEDULE t left join BOK_SCHEME_INFO b on t.SCH_ID=b.SCH_ID INNER JOIN Data_Auth_Notify_Inst dani ON dani.business_id = t.tax_id AND dani.model_type = '02' AND dani.data_type = 'TAXADT'
#{item,jdbcType=VARCHAR}
AND t.tax_id in
#{item}
AND t.SCH_ID = #{schId}
AND t.add_tax_type in
#{item}
and t.eff_date >= to_date(#{effDateBegin},'yyyy-mm-dd')
and t.eff_date <= to_date(#{effDateEnd},'yyyy-mm-dd')
and t.eff_date = to_date(#{effDate},'yyyy-mm-dd')
AND t.tax_id != #{owner}
union all
select t.tax_id as taxId, /*税则代码 */ t.sch_id as schId, /* 方案代码 */ b.IS_DEFAULT as isDefault ,/**是否默认**/ t.add_tax_type as addTaxType, /* 附加税类型 */ t.add_tax_type as addTaxTypeCode, t.tax_rate*100 as taxRate, /* 应税税率(%) */ TO_CHAR(t.eff_date, 'yyyy-MM-dd') as effDate/* 生效日 */ , '' belongInstitutionCode ,'02' updateFlg from TAX_ADT_SCHEDULE t left join BOK_SCHEME_INFO b on t.SCH_ID=b.SCH_ID
AND t.tax_id in
#{item}
AND t.SCH_ID = #{schId}
AND t.add_tax_type in
#{item}
and t.eff_date >= to_date(#{effDateBegin},'yyyy-mm-dd')
and t.eff_date <= to_date(#{effDateEnd},'yyyy-mm-dd')
and t.eff_date = to_date(#{effDate},'yyyy-mm-dd')
AND t.tax_id != #{owner}
AND NOT EXISTS ( SELECT 1 FROM Data_Auth_Notify_Inst dani WHERE dani.business_id = t.tax_id AND dani.model_type = '02' AND dani.data_type = 'TAXADT' )

select tti.seq_no as seqNo, /*流水号*/ tti.sch_id as schId, /*方案代码*/ a.assetId as assetId, /*资产代码*/ a.assetName as assetName, /*资产名称*/ b.IS_DEFAULT as isDefault ,/**是否默认**/ tti.asset_classify as assetClassify, /*资产分类*/ tti.asset_classify as assetClassifyCode, tti.capi_income_feature as capiIncomeFeature, /*本金收益特征*/ tti.capi_income_feature as capiIncomeFeatureCode, tti.income_type as incomeType, /*收入类型*/ tti.income_type as incomeTypeCode, tti.taxable_sign as taxableSign, /*计税方式 - 应税标识*/ tti.taxable_sign as taxableSignCode, tti.tax_rate*100 as taxRate, /*应税税率(%)*/ TO_CHAR(tti.eff_date, 'yyyy-MM-dd') as effDate, /*生效日*/ tti.maintenance_mode as maintenanceMode, /*维护方式*/ tti.maintenance_mode as maintenanceModeCode, tti.fee_type as feeTypeCode, tti.fee_type as feeType /*免税收入类型*/ from TAX_TAXABLE_INFO tti inner join (
select nvl(fp.finprod_market_id, fp.finprod_id) as assetId, /*资产代码*/ nvl(fp.finprod_abbr, fp.finprod_name) as assetName, /*资产名称*/ fp.finprod_id as originalFinprodId /*资产代码*/ from fin_product_type fpt inner join fin_product fp on fp.finprod_id = fpt.finprod_id where fpt.type_3 is not null
union all
select ftp.finprod_id as assetId, /*资产代码*/ ftp.finprod_id as assetName, /*资产名称*/ ftp.finprod_id as originalFinprodId /*资产代码*/ from fin_product_type fpt inner join fin_trade_product ftp on ftp.finprod_id = fpt.finprod_id where fpt.type_3 is not null and ftp.branch = '0'
) a on a.originalFinprodId = tti.asset_id left join BOK_SCHEME_INFO b on tti.SCH_ID=b.SCH_ID
AND tti.seq_no in
#{item}
AND tti.SCH_ID = #{schId}
AND tti.asset_classify in
#{item}
AND a.assetId in
#{item}
AND tti.capi_income_feature in
#{item}
AND tti.income_type in
#{item}
AND tti.taxable_sign in
#{item}
and tti.eff_date >= to_date(#{effDateBegin},'yyyy-mm-dd')
and tti.eff_date <= to_date(#{effDateEnd},'yyyy-mm-dd')
AND tti.maintenance_mode in
#{item}
and tti.eff_date = to_date(#{effDate},'yyyy-mm-dd')
AND tti.seq_no != #{owner}

select tas.scheme_type_2 as schemeType2 ,/* 参数类型 */ tas.scheme_type_2 as schemeType2Code , tas.config_id as configId ,/* 项目代码 */ b.IS_DEFAULT as isDefault ,/**是否默认**/ tas.config_name as configName ,/* 项目 */ tas.remark as remark ,/* 项目说明 */ tas.dict_code as dictCode, /* 数据字典 */ val.scheme_id as schemeId ,/* 方案代码 */ val.seq_id as seqId ,/* 代码 */ val.config_value as configValue ,/* 值 */ val.config_value as configValueCode ,/* 值 */ TO_CHAR(val.eff_date, 'yyyy-MM-dd') as effDate/*生效日*/ from bok_scheme_config tas inner join bok_scheme_config_val val on tas.config_id = val.config_id left join BOK_SCHEME_INFO b on val.SCHEME_ID = b.SCH_ID
AND seq_id in
#{item}
AND tas.config_id in
#{item}
AND tas.scheme_type_2 in
#{item}
AND val.scheme_id in
#{item}
and val.eff_date >= to_date(#{effDateBegin},'yyyy-mm-dd')
and val.eff_date <= to_date(#{effDateEnd},'yyyy-mm-dd')
and val.eff_date = to_date(#{effDate},'yyyy-mm-dd')
AND val.seq_id != #{owner}

select TBC.config_id as configId, /*配置代码*/ TBC.table_id as tableId, /*记账场景(会计事件编码)*/ TBC.table_id as tableIdCode, /*记账场景(会计事件编码)*/ (select n.SUBJECT_INTERNAL_NAME from BOK_SUBJECT_INTERNAL n where n.SUBJECT_INTERNAL_CODE = TBC.subject_nature) as subjectNature, /*发生额科目性质*/ TBC.subject_nature as subjectNatureCode, /*发生额科目性质*/ TBC.vat_type as vatType, /*增值税类型*/ TBC.vat_type as vatTypeCode, /*增值税类型*/ TBC.tax_p_type as taxPType, /*确认类型*/ TBC.tax_p_type as taxPTypeCode, /*确认类型*/ TBC.income_source as incomeSource, /*发生场景*/ TBC.income_source as incomeSourceCode, /*发生场景*/ TBC.in_out as inOut, /*增项/减项*/ TBC.in_out as inOutCode, /*增项/减项*/ TBC.calc_type as calcType, /*计算方式*/ TBC.calc_type as calcTypeCode, /*计算方式*/ TBC.cd_flag as cdFlag, /*发生科目借贷方向*/ TBC.cd_flag as cdFlagCode, /*发生科目借贷方向*/ TBC.calc_scale as calcScale, /*占比方式*/ TBC.calc_scale as calcScaleCode, /*占比方式*/ (select n.subject_nature_name from BOK_ACCT_STANDARD_NATURE n where n.base_subject_nature = TBC.calc_snature) as calcSnature, /*占比科目科目性质*/ TBC.calc_snature as calcSnatureCode, /*占比科目科目性质*/ TBC.calc_base as calcBase, /*占比基数*/ TBC.calc_base as calcBaseCode, /*占比基数*/ TBC.is_carrt as isCarrt, /*金额计入方式*/ TBC.int_repay_handle as intRepayHandle, /*处理条件*/
TSBC.seq_no as seqNo, /*流水号*/ TSBC.Scheme_Id as schemeId /*流水号*/ from TAX_BOK_CONFIG TBC inner join TAX_SCHA_BOK_CONFIG TSBC on TBC.config_id = TSBC.bok_config_id and TSBC.scheme_id = #{schemeId}
AND TBC.config_id in
#{item}
AND TBC.table_id in
#{item}
AND TBC.vat_type in
#{item}
AND TSBC.seq_no in
#{item}
AND TSBC.seq_no != #{owner}
